example:
context shop

consumes bynk.cloudflare { InboundEmail, EmailVerdict }

service support from email("support@shop.example") {
  on message(mail: InboundEmail) -> Effect[EmailVerdict] {   // ✗ what mail does this act on?
    Accept
  }
}

service support from email("support@shop.example") {
  on message(mail: InboundEmail) -> Effect[EmailVerdict] by Sender {   // ✓ any mail, said outright
    Accept
  }
}
